def bubble_sort(data):
    # Bubble Sort: bandingkan elemen bersebelahan berulang kali
    arr = data.copy()
    n = len(arr)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

