# Produk E-Commerce: pengurutan harga produk pakai Merge Sort
def merge(kiri, kanan):
    gabung = []
    i = j = 0
    while i < len(kiri) and j < len(kanan):
        if kiri[i] <= kanan[j]:
            gabung.append(kiri[i]); i += 1
        else:
            gabung.append(kanan[j]); j += 1
    gabung.extend(kiri[i:])
    gabung.extend(kanan[j:])
    return gabung

def merge_sort(data):
    # Merge Sort: bagi dua terus sampai 1 elemen, lalu gabungkan
    if len(data) <= 1:
        return data
    tengah = len(data) // 2
    kiri = merge_sort(data[:tengah])
    kanan = merge_sort(data[tengah:])
    return merge(kiri, kanan)

